keyframes.css:
@keyframes cueDot { 
  0% { transform: translateY(-10px); opacity: 0; }
  25% { opacity: 1; }
  75% { opacity: 1; }
  100% { transform: translateY(44px); opacity: 0; }
}

@keyframes fadeDown { 
  0% { opacity: 0; transform: translateY(-16px); }
  100% { opacity: 1; transform: translateY(0px); }
}
